import{_ as t,o,c as s,a2 as a}from"./chunks/framework.D66Xq0Kv.js";const p=JSON.parse('{"title":"Model Test","description":"","frontmatter":{"title":"Model Test"},"headers":[],"relativePath":"docs/tools/model-test.md","filePath":"docs/tools/model-test.md","lastUpdated":1791955898000}'),r={name:"docs/tools/model-test.md"};function l(n,e,i,d,c,h){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="model-test" tabindex="-1">Model Test <a class="header-anchor" href="#model-test" aria-label="Permalink to &quot;Model Test&quot;">​</a></h1><p>Before relying on a model you&#39;ve configured, Model Test checks that it works correctly with OrbySystems. It confirms that the model and its endpoint honor what OrbySystems assumes of them — well-formed tool calls, reproducible answers, and truncation reported honestly. It is a compatibility check, not a measure of how good the model is.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><p>Pick a configured model and click <strong>Run checks</strong>. Each check shows its own question, what it&#39;s looking for, and the full transcript, so you can see exactly what happened if something fails.</p><p>Model Test never starts a model server itself. A local model must already be running, which you control in <a href="/docs/settings/models">Settings → Models</a>. It talks to the endpoint directly, so it is safe to run while you are in a conversation.</p>',5)])])}const u=t(r,[["render",l]]);export{p as __pageData,u as default};
